/** Even distribution (§5.20): spread the hand over the entities, deterministically */
export interface DistributeAction {
  item: number;
  count: number;
  entities: EntityRef[];
}
export const DistributeActionCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 6,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { item: 0, count: 2 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): DistributeAction {
    return { item: 0, count: 0, entities: [] };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    item: (v: DataView, o: number): number => v.getUint16(o + 0, true),
    count: (v: DataView, o: number): number => v.getUint32(o + 2, true),
  },
  read(r: Reader): DistributeAction {
    
    const f_item = ItemKeyCodec.read(r, "DistributeAction.item");
    const f_count = r.u32("DistributeAction.count");
    const f_entities = readList(r, 2, 4096, "DistributeAction.entities", 8, () => EntityRefCodec.read(r, "DistributeAction.entities"));
    
    return { item: f_item, count: f_count, entities: f_entities };
  },
  write(w: Writer, v: DistributeAction): void {
    
    ItemKeyCodec.write(w, v.item, "DistributeAction.item");
    w.u32(v.count, "DistributeAction.count");
    w.count(v.entities.length, 2, 4096, "DistributeAction.entities"); for (const x of v.entities) { EntityRefCodec.write(w, x, "DistributeAction.entities"); }
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): DistributeAction {
    const r = new Reader(bytes);
    const v = DistributeActionCodec.read(r);
    r.finish("DistributeAction");
    return v;
  },
  /** Encodes one value. */
  encode(v: DistributeAction): Uint8Array {
    const w = new Writer();
    DistributeActionCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: DistributeAction, prefix = ''): void {
    d.int(`${prefix}item`, v.item);
    d.int(`${prefix}count`, v.count);
    d.int(`${`${prefix}entities`}.len`, v.entities.length); v.entities.forEach((x, i) => { EntityRefCodec.dump(d, x, `${`${`${prefix}entities`}[${i}]`}.`); });
  },
};

