export interface PlaceBlueprintAction {
  pos: TilePos2;
  dir: number;
  flip: boolean;
  mode: number;
  /** inline bytes (tag 0) up to the payload limit, else a blob of at most 8 MiB (11 §3.2) named by its SHA-256 (tag 1) */
  record: BlobOrBytes;
}
export const PlaceBlueprintActionCodec = {
  /** The bytes before the first variable-length field. */
  PREFIX: 12,
  /** Byte offsets of the fields in the fixed prefix. */
  OFFSET: { pos: 0, dir: 8, flip: 9, mode: 10 },
  /** A value with every field at its default (optional fields absent). */
  defaults(): PlaceBlueprintAction {
    return { pos: TilePos2Codec.defaults(), dir: 0, flip: false, mode: 0, record: { bytes: new Uint8Array(0) } };
  },
  /** Field reads at byte offset `o` of a DataView (no validation: for records already validated). */
  get: {
    dir: (v: DataView, o: number): number => v.getUint8(o + 8),
    flip: (v: DataView, o: number): boolean => v.getUint8(o + 9) !== 0,
    mode: (v: DataView, o: number): number => v.getUint8(o + 10),
  },
  read(r: Reader): PlaceBlueprintAction {
    
    const f_pos = TilePos2Codec.read(r, "PlaceBlueprintAction.pos");
    const f_dir = DirectionCodec.read(r, "PlaceBlueprintAction.dir");
    const f_flip = r.bool("PlaceBlueprintAction.flip");
    const f_mode = BuildModeCodec.read(r, "PlaceBlueprintAction.mode");
    r.zeros(1, "PlaceBlueprintAction.reserved");
    const f_record = readBlobOrBytes(r, 65516, "PlaceBlueprintAction.record");
    
    return { pos: f_pos, dir: f_dir, flip: f_flip, mode: f_mode, record: f_record };
  },
  write(w: Writer, v: PlaceBlueprintAction): void {
    
    TilePos2Codec.write(w, v.pos, "PlaceBlueprintAction.pos");
    DirectionCodec.write(w, v.dir, "PlaceBlueprintAction.dir");
    w.bool(v.flip, "PlaceBlueprintAction.flip");
    BuildModeCodec.write(w, v.mode, "PlaceBlueprintAction.mode");
    w.zeros(1);
    writeBlobOrBytes(w, v.record, 65516, "PlaceBlueprintAction.record");
    
  },
  /** Decodes one value that fills `bytes` exactly. */
  decode(bytes: Uint8Array): PlaceBlueprintAction {
    const r = new Reader(bytes);
    const v = PlaceBlueprintActionCodec.read(r);
    r.finish("PlaceBlueprintAction");
    return v;
  },
  /** Encodes one value. */
  encode(v: PlaceBlueprintAction): Uint8Array {
    const w = new Writer();
    PlaceBlueprintActionCodec.write(w, v);
    return w.finish();
  },
  dump(d: Dump, v: PlaceBlueprintAction, prefix = ''): void {
    TilePos2Codec.dump(d, v.pos, `${`${prefix}pos`}.`);
    d.int(`${prefix}dir`, v.dir);
    d.bool(`${prefix}flip`, v.flip);
    d.int(`${prefix}mode`, v.mode);
    dumpBlobOrBytes(d, `${prefix}record`, v.record);
  },
};

